steps:
Passo 4: Verifique a quantidade de núcleos não preposicionados:
   - 1 núcleo expresso = Simples;
   - 2 ou mais núcleos = Composto;
   - Desinência verbal clara (nós, eu) = Oculto;
   - Verbo na 3ª plural sem dono = Indeterminado.

structure.mermaidSource:
flowchart TD
  start["Início: Diagnóstico do Sujeito"] --> proc_isolar_verbo["Passo 1: Isolar o verbo da oração"]
  proc_isolar_verbo --> dec_impessoal{"O verbo é impessoal? (Haver = existir/tempo; Fazer = clima/tempo)"}
  dec_impessoal -- "Sim" --> res_sem_sujeito["ORAÇÃO SEM SUJEITO (Sujeito Inexistente / Verbo Impessoal 3ª sing)"]
  dec_impessoal -- "Não" --> dec_tem_se{"Há presença da partícula 'SE' ligada ao verbo?"}
  dec_tem_se -- "Sim (Passo 3)" --> dec_passiva_analitica{"Consegue converter para voz passiva analítica? (Ex: 'Casas são alugadas')"}
  dec_passiva_analitica -- "Sim" --> res_sujeito_paciente["SE = Partícula Apassivadora (PA) -> Termo não preposicionado é SUJEITO PACIENTE"]
  dec_passiva_analitica -- "Não" --> dec_tem_prep_iis{"Não converte e há preposição após o verbo? (Ex: 'de operários')"}
  dec_tem_prep_iis -- "Sim" --> res_sujeito_indeterminado_iis["SE = Índice de Indeterminação (IIS) -> SUJEITO INDETERMINADO"]
  dec_tem_prep_iis -- "Não" --> proc_pergunta_quem["Passo 2: Perguntar 'QUEM / O QUE é que + verbo?'"]
  dec_tem_se -- "Não" --> proc_pergunta_quem
  proc_pergunta_quem --> dec_sujeito_expresso{"A resposta à pergunta está expressa na oração sem preposição?"}
  dec_sujeito_expresso -- "Sim (Passo 4)" --> dec_qtd_nucleos{"Quantos núcleos substantivos não preposicionados existem?"}
  dec_qtd_nucleos -- "1 núcleo" --> res_sujeito_simples["SUJEITO DETERMINADO SIMPLES"]
  dec_qtd_nucleos -- "2 ou mais núcleos" --> res_sujeito_composto["SUJEITO DETERMINADO COMPOSTO"]
  dec_sujeito_expresso -- "Não (Sujeito Implícito)" --> dec_tipo_implicito{"Como se comporta o verbo no contexto oracional?"}
  dec_tipo_implicito -- "Desinência verbal clara (eu, nós, etc.)" --> res_sujeito_oculto["SUJEITO OCULTO / DESINENCIAL / ELÍPTICO"]
  dec_tipo_implicito -- "3ª pessoa do plural sem referente prévio" --> res_sujeito_indeterminado_plural["SUJEITO INDETERMINADO (Verbo na 3ª pessoa do plural)"]
